html body #site .pm-index .nb-index-no { align-self: start; font: 700 25px/1.6 var(--product-english-font); color: #31556e; font-variant-numeric: lining-nums tabular-nums; }
html body #site .pm-index .nb-index-name { align-self: start; color: var(--product-ink); font-size: 25px; font-weight: 700; line-height: 1.6; }
html body #site .pm-index .nb-index-name>small { display: block; margin-top: 5px; color: var(--product-muted); font-size: 14px; font-weight: 400; line-height: 1.85; }
html body #site .pm-index .nb-index-example { display: none; }
/* Optional learning preview; the lesson description remains available without hovering. */
.px-lesson-preview { position: fixed; z-index: 85; box-sizing: border-box; padding: 17px 19px; border: 1px solid #d1dfd9; border-radius: 16px; background: #fffefa; color: #193b50; box-shadow: 0 10px 28px #193b4b1a,0 2px 5px #193b4b08; font: 400 14px/1.8 var(--product-ui-font); text-align: start; animation: px-learning-preview-in 150ms var(--ease-emphasized); }
.px-lesson-preview[hidden] { display: none; }
.px-lesson-preview .px-preview-eyebrow { display: block; color: #4e6f60; font-size: 12px; font-weight: 500; margin-bottom: 2px; }
.px-lesson-preview>strong { display: block; font-size: 17px; font-weight: 600; line-height: 1.7; }
.px-lesson-preview>ul { margin: 9px 0 0; padding-inline-start: 18px; color: #3e5b69; }
.px-lesson-preview li+li { margin-top: 3px; }
@keyframes px-learning-preview-in { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
/* The earned count is clear, with a quiet zero state and the original native disclosure. */
html body #site .jt-awards-area:empty { display: none; }
html body #site .jt-achievements>.px-achievement-summary { gap: 18px; padding: 18px 22px; }
html body #site .px-achievement-summary>span:first-child { flex: 1 1 auto; min-inline-size: 0; }
html body #site .px-achievement-summary strong { font-size: 19px; }
html body #site .px-achievement-summary small { font-size: 13px; margin-top: 3px; color: #536c60; }
html body #site .px-achievement-count { display: inline-flex; align-items: baseline; justify-content: center; gap: 5px; flex: 0 0 auto; min-inline-size: 76px; padding: 7px 12px; border: 1px solid transparent; border-radius: 12px; background: transparent; color: #597064; white-space: nowrap; }
html body #site .px-achievement-count>bdi { font: 700 27px/1.2 var(--product-english-font); font-variant-numeric: lining-nums tabular-nums; }
html body #site .px-achievement-count>span { font-size: 13px; font-weight: 500; }
html body #site .px-has-awards .px-achievement-count { border-color: #bdd5c5; background: #eaf4ed; color: #28583e; }
html body #site .px-has-awards .px-achievement-count>bdi { font-size: 32px; }
@media(max-width:700px) {
  html body #site .jt-achievements>.px-achievement-summary { gap: 11px; padding: 16px 14px; }
  html body #site .px-achievement-summary strong { font-size: 17px; }
  html body #site .px-achievement-summary small { font-size: 12px; }
  html body #site .px-achievement-count { min-inline-size: 60px; padding: 6px 8px; border-radius: 10px; }
  html body #site .px-achievement-count>bdi { font-size: 24px; }
  html body #site .px-has-awards .px-achievement-count>bdi { font-size: 29px; }
}
@media(max-width:430px) { html body #site .px-achievement-summary>span:first-child>.jt-award-mark { display: none; } }
/* Connectors follow the rendered blocks, keeping branch labels in free space. */
html body #site .builder-connectors .px-flow-line { fill: none; stroke: #376b8f; stroke-width: 2; vector-effect: non-scaling-stroke; }
html body #site .builder-connectors .px-flow-yes { stroke: #2d785c; }
