html body #site .builder-alternative { background: transparent; }
html body #site .builder-alternative small { font-size: 11px; line-height: 1.7; padding: 6px 8px; }
html body #site .pm-index .pm-index-status { display: grid; grid-template-columns: 1fr; gap: 6px; }
html body #site .pm-index-status>strong { display: inline-flex; align-items: center; gap: 7px; font-size: 15px; line-height: 1.8; font-weight: 600; }
html body #site .pm-index-status>small { font-size: 13px; line-height: 1.7; color: var(--product-muted); }
html body #site .pm-index-status>.pm-track { grid-column: auto; grid-row: auto; block-size: 5px; margin-top: 3px; }
html body #site .pm-index .pm-row.is-complete { background: #f0f7f1; border-color: #c9dfcf; }
html body #site .pm-index .pm-row.is-started { background: #f0f6fb; border-color: #bdd2e1; box-shadow: none; }
html body #site .pm-index .pm-row.px-ready { background: #f8f7ed; border-color: #dad6b8; }
html body #site .pm-index .pm-row.is-new { background: transparent; }
html body #site .pm-index .pm-state-icon { display: inline-flex; align-items: center; gap: 7px; inline-size: auto; block-size: auto; min-block-size: 44px; border: 0; border-radius: 0; background: none; color: #255e82; font-size: 13px; font-weight: 600; padding: 0; box-shadow: none; }
html body #site .pm-lesson-position { background: #f3f7fa; border: 1px solid var(--product-rule); border-radius: 14px; padding: 22px; }
html body #site .pm-lesson-position.is-complete { background: #f1f8f3; border-color: #c5decd; }
html body #site .pm-position-top strong { font-size: 20px; font-weight: 700; }
html body #site .pm-position-caption { font-size: 14px; }
html body #site .pm-save-state { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; }
html body #site .pm-milestones>li>span { display: inline-flex; align-items: center; justify-content: center; font: 600 16px/1 var(--product-english-font); }
html body #site .pm-milestones>li>b { font-size: 14px; font-weight: 600; }
/* Two clear study steps; the current step is navigation state, not an answer result. */
html body #site .ux-stepper { display: block; margin: 20px 0 24px; padding: 0; scroll-margin-top: 12px; }
html body #site .ux-stepper>div { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 6px; padding: 5px; border: 1px solid #d5dfda; border-radius: 18px; background: #f0f4f1; }
html body #site .ux-stepper .px-lesson-step { display: flex; align-items: center; justify-content: center; gap: 10px; min-inline-size: 0; min-block-size: 56px; padding: 10px 14px; border: 1px solid transparent; border-radius: 13px; background: transparent; color: #4a6372; font-size: 15px; font-weight: 600; line-height: 1.6; box-shadow: none; transform: none; }
html body #site .px-step-number { display: grid; place-items: center; flex: 0 0 28px; inline-size: 28px; block-size: 28px; border-radius: 50%; background: #e4ebe5; border: 1px solid #d4dfd7; color: #526b61; font: 600 17px/1 var(--product-english-font); }
html body #site .px-step-label { min-inline-size: 0; }
html body #site .ux-stepper .px-lesson-step[aria-current=step] { background: #fffefa; border-color: #b8cdd8; color: #1d4c69; font-weight: 700; box-shadow: 0 2px 5px #183d4a08; }
html body #site .px-lesson-step[aria-current=step] .px-step-number { background: #245a77; border-color: #245a77; color: #fff; }
@media(hover:hover) and (pointer:fine) { html body #site .ux-stepper .px-lesson-step:hover { background: #f8fbf7; border-color: #c1d3c9; box-shadow: none; transform: none; } }
html body #site .ux-stepper .px-lesson-step:active { background: #e6eee8; transform: none; }
html body #site .ux-stepper .px-lesson-step:focus-visible { outline: 3px solid #096fbd; outline-offset: 2px; }
@media(max-width:430px) {
  html body #site .ux-stepper .px-lesson-step { gap: 7px; padding: 9px 7px; font-size: 14px; }
  html body #site .px-step-number { flex-basis: 26px; inline-size: 26px; block-size: 26px; font-size: 16px; }
}
/* Verified answer results use a filled disc and a white check/cross, as in the reference. */
html body :is(#site,#dialog) .feedback { align-items: flex-start; gap: 12px; padding: 16px 18px; border-radius: 12px; }
html body :is(#site,#dialog) .feedback>span[aria-hidden] { display: flex; align-items: center; justify-content: center; flex: 0 0 34px; inline-size: 34px; min-inline-size: 34px; block-size: 34px; margin: 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
html body :is(#site,#dialog) .feedback>div { min-inline-size: 0; }
html body :is(#site,#dialog) .feedback p { overflow-wrap: anywhere; }
html body #site .practice-question>.feedback+.actions { margin-block-start: 12px; }
.px-result-icon { display: block; inline-size: 32px; block-size: 32px; flex: 0 0 32px; }
.px-result-correct { color: #2f8752; }
.px-result-incorrect { color: #d14145; }
html body #site .px-correction-state { display: inline-flex; align-items: center; gap: 6px; vertical-align: middle; }
html body #site .px-compact-result { inline-size: 23px; block-size: 23px; flex: 0 0 23px; }
html body #site .nb-mini-mark { margin-inline-start: 5px; }
html body #site .nb-slot-status { inline-size: 25px; block-size: 25px; background: none; border: 0; }
