html body #site .nb-inline-field-state { top: -8px; right: -8px; inline-size: 22px; block-size: 22px; border: 0; background: var(--ds-surface); }
html body #site .px-graded-part { display: inline-flex; align-items: center; justify-content: center; gap: 7px; padding-inline: 10px; }
html body #site .review-detail summary>.px-correction-state { flex-wrap: wrap; row-gap: 3px; }
html body :is(#site,#dialog) .question-numbers button.answered::after { content: ''; inline-size: 5px; block-size: 5px; inset: auto 5px 4px auto; border-radius: 50%; background: #597b78; }
html body #site .pm-sidebar>span { font: 700 18px/1 var(--product-english-font); }
html body #site .jt-tab-state { display: inline-flex; align-items: center; gap: 5px; font-size: 13px; }
html body #site .jt-tab-state .px-state-icon { inline-size: 16px; block-size: 16px; }
html body #site .jt-tab-state .px-tab-result { inline-size: 19px; block-size: 19px; flex: 0 0 19px; }
html body #site .result-counts b { font: 700 27px/1.4 var(--product-english-font); }
html body #site .pm-step-guidance { font-size: 14px; line-height: 1.85; color: var(--product-body); }
html body #site .lesson-complete { border-radius: 14px; padding: 24px; }
html body #site .lesson-complete h3 { display: flex; align-items: center; gap: 8px; font-size: 21px; font-weight: 700; }
html body #site .ds-storage-status { min-block-size: 28px; font-size: 15px; font-weight: 500; }
html body #site .ds-storage-status .ds-save-icon { inline-size: 20px; block-size: 20px; flex-basis: 20px; }
html body #site .ds-footer-utilities .ds-action { font-size: 14px; font-weight: 600; }
html body #site .nb-colophon-links { flex-wrap: wrap; }
html body #site .nb-colophon-links .ds-action.px-social-link { gap: 9px; min-block-size: 48px; padding-inline: 16px; white-space: nowrap; text-decoration: none; }
html body #site .px-social-icon { display: block; inline-size: 24px; block-size: 24px; flex: 0 0 24px; object-fit: contain; }
html body #site .px-social-external { inline-size: 14px; block-size: 14px; flex: 0 0 14px; color: inherit; }
html body #site .px-social-note { position: absolute; inline-size: 1px; block-size: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@media(hover:hover) and (pointer:fine) {
