  html body #site .nb-colophon-links .ds-action.px-social-whatsapp:hover { color: #286444; border-color: #abc8b3; background: #edf5ec; }
}
html body #site .nb-colophon-links .ds-action.px-social-link:active { background: #eae3d7; transform: none; }
@media(max-width:480px) {
  html body #site .nb-colophon-links { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px; inline-size: 100%; }
  html body #site .nb-colophon-links .ds-action.px-social-link { inline-size: 100%; padding-inline: 10px; gap: 7px; font-size: 14px; }
  html body #site .px-social-icon { inline-size: 22px; block-size: 22px; flex-basis: 22px; }
  html body #site .px-social-external { inline-size: 12px; block-size: 12px; flex-basis: 12px; }
