/* Selection is neutral blue; correctness is reserved for verified results. */
html body #site .practice-question .answer-option { border-radius: 8px; gap: 12px; }
html body #site .answer-option :is(.px-choice-indicator,.nx-choice-indicator) { display: grid; place-items: center; flex: 0 0 18px; inline-size: 18px; block-size: 18px; border: 1.5px solid #9eb3c1; border-radius: 50%; background: #fff; color: #2c678d; box-shadow: none; }
html body #site .answer-option .nx-choice-indicator { inline-size: 22px; block-size: 22px; justify-self: center; }
html body #site .answer-option :is(.px-choice-indicator,.nx-choice-indicator)::after { content: ''; display: block; inline-size: 6px; block-size: 6px; border-radius: 50%; background: currentColor; opacity: 0; }
html body #site .answer-option:is(.selected,[aria-checked=true]):not(.nb-choice-correct):not(.nb-choice-incorrect) { background: #edf5fb; border-color: #5a8eae; color: #193d56; box-shadow: inset 0 0 0 1px #5a8eae; }
html body #site .answer-option:is(.selected,[aria-checked=true]) :is(.px-choice-indicator,.nx-choice-indicator) { border-color: #39769c; background: #fff; color: #2c678d; }
