html body #site .answer-option .option-number { font-family: var(--product-english-font); font-weight: 600; border-radius: 6px; }
html body #site .answer-option:is(.selected,[aria-checked=true]):not(.nb-choice-correct):not(.nb-choice-incorrect) .option-number { border-color: #9bb9cb; background: #f8fcff; color: #285b7a; }
html body #site .answer-option.nb-choice-correct { box-shadow: inset 0 0 0 1px #4f8d65; }
html body #site .answer-option.nb-choice-incorrect { box-shadow: inset 0 0 0 1px #b55262; }
html body #site .answer-option.nb-choice-correct .option-number { border-color: #a1c3ab; background: #f6fbf7; color: #35664a; }
html body #site .answer-option.nb-choice-incorrect .option-number { border-color: #d3a3ac; background: #fff8f8; color: #913b49; }
html body #site .answer-option:is(.nb-choice-correct,.nb-choice-incorrect):disabled { opacity: 1; cursor: default; }
html body #site .answer-option .nb-answer-state { display: inline-flex; align-items: center; gap: 7px; margin-inline-start: 0; font-size: 12px; font-weight: 500; line-height: 1.7; }
html body #site .nb-answer-state .px-option-result { inline-size: 25px; block-size: 25px; flex: 0 0 25px; }
html body #site .nb-choice-correct .nb-answer-state { color: #2c7448; }
html body #site .nb-choice-incorrect .nb-answer-state { color: #b43640; }
:root { --review-flag-ink: #9b3d22; --review-flag-tint: #fff0e5; --review-flag-border: #d9a17d; }
