/* Shared modal/notification language. The safe reset option receives initial focus. */
html body #dialog.modal { inline-size: min(570px,calc(100% - 32px)); max-inline-size: none; max-block-size: calc(100dvh - 40px); margin: auto; padding: 30px; border: 1px solid #d5e0e7; border-radius: 22px; background: #fff; color: var(--product-ink); box-shadow: 0 24px 80px #0c263432; }
html body #dialog[data-tone=map] { inline-size: min(780px,calc(100% - 32px)); }
html body #dialog::backdrop { background: #102b4260; backdrop-filter: blur(3px); }
html body #dialog .nb-dialog-heading { padding: 0 0 20px; }
html body #dialog .nb-dialog-heading h2 { font-size: 27px; font-weight: 700; line-height: 1.6; margin-block: 10px; }
html body #dialog #dialog-description { font-size: 16px; line-height: 1.85; color: var(--product-muted); }
