/* One global navigation system, shared by the home page and learning routes. */
html { scroll-padding-top: 108px; }
html body #site #navigation.ed-nav {
  position: sticky; z-index: 70; inset: 0 auto auto; transform: none;
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  inline-size: 100%; max-inline-size: none; min-block-size: 80px;
  padding: 12px max(24px,calc((100% - 1280px)/2));
  background: #fffdf7f5; color: #193b52; border: 0; border-bottom: 1px solid #d7e1dc;
  border-radius: 0; box-shadow: none; backdrop-filter: blur(16px);
}
html body #site.ed-home #navigation.ed-nav {
  position: fixed; top: 20px; left: 50%; right: auto; transform: translateX(-50%);
  inline-size: min(1280px,calc(100% - 64px)); padding: 12px 18px;
  border: 1px solid #dce5dc; border-radius: 999px;
  box-shadow: 0 5px 22px #173b4910;
}
html body #site.ed-home #navigation.compact { background: #fffdf8fa; box-shadow: 0 6px 24px #173b491a; }
html body #site #navigation .ed-brand { display: inline-flex; align-items: center; justify-content: center; gap: 12px; flex: 0 0 auto; min-inline-size: 48px; min-block-size: 48px; color: #18394f; font-size: 26px; line-height: 1.3; white-space: nowrap; text-decoration: none; }
html body #site #navigation .ed-brand strong { font-weight: 700; }
html body #site #navigation .ed-brand img { display: block; inline-size: 48px; block-size: 52px; object-fit: contain; border: 0; border-radius: 0; background: transparent; }
html body #site #navigation .ed-nav-links { display: flex; align-items: center; gap: 6px; min-inline-size: 0; }
html body #site #navigation .ed-nav-links>a { display: flex; align-items: center; justify-content: center; gap: 10px; min-block-size: 48px; padding: 10px 13px; border: 1px solid transparent; border-radius: 999px; color: #3a5262; font-size: 16px; font-weight: 600; line-height: 1.6; white-space: nowrap; text-decoration: none; transition: background-color var(--motion-fast),border-color var(--motion-fast),color var(--motion-fast); }
html body #site #navigation .ed-nav-links>a[aria-current=page] { background: #f2eddf; border-color: #e0d5ba; color: #193d52; font-weight: 700; }
html body #site #navigation .ed-nav-links>a::after { content: none; }
html body #site #navigation .ds-action.ds-primary { --action-icon: 34px; min-block-size: 48px; padding: 5px 14px 5px 5px; gap: 10px; flex: 0 0 auto; font-size: 15px; font-weight: 700; }
html body #site #navigation .ds-action>.jt-button-label { white-space: nowrap; }
html body #site #navigation .ds-action .px-action-icon { inline-size: 20px; block-size: 20px; }
html body #site #navigation .ed-menu-toggle { display: none; align-items: center; justify-content: center; gap: 7px; flex: 0 0 auto; min-inline-size: 48px; min-block-size: 48px; padding: 8px 10px; border: 1px solid #cad8d2; border-radius: 14px; background: #f6f7ef; color: #25485b; font-size: 14px; line-height: 1.4; cursor: pointer; }
html body #site #navigation .ed-menu-toggle .px-ui-icon { inline-size: 23px; block-size: 23px; }
html body #site #navigation .ed-menu-toggle[aria-expanded=true] { background: #eaf0e8; border-color: #91ad9c; }
html body #site #navigation .ed-nav-links>a:is(:active,.ds-pressed),html body #site #navigation .ed-menu-toggle:active { background: #e8e5d7; transform: none; }
html body #site #navigation :is(a,button):focus-visible { outline: 3px solid #096fbd; outline-offset: 3px; }
@media(hover:hover) and (pointer:fine) {
  html body #site #navigation .ed-nav-links>a:hover { background: #f6f1e5; border-color: #e2decd; color: #153a52; text-decoration: none; }
  html body #site #navigation .ed-menu-toggle:hover { background: #edf1e8; }
}
@media(max-width:1100px) and (min-width:1001px) {
  html body #site #navigation .ed-brand { font-size: 23px; gap: 9px; }
  html body #site #navigation .ed-nav-links>a { padding-inline: 10px; }
}
@media(max-width:1000px) {
  html body #site #navigation.ed-nav { display: grid; grid-template-columns: auto minmax(0,1fr) auto; gap: 12px; padding-inline: 22px; }
  html body #site.ed-home #navigation.ed-nav { inline-size: calc(100% - 40px); padding-inline: 16px; }
  html body #site #navigation .ed-brand { grid-column: 1; }
  html body #site #navigation #nav-start { grid-column: 2; justify-self: end; }
  html body #site #navigation .ed-menu-toggle { display: inline-flex; grid-column: 3; }
  html body #site #navigation .ed-nav-links { display: none; }
  html body #site #navigation .ed-nav-links.open { position: absolute; inset: calc(100% + 8px) 0 auto; display: flex; flex-direction: column; align-items: stretch; gap: 6px; max-block-size: calc(100dvh - 120px); padding: 12px; overflow-y: auto; overscroll-behavior: contain; border: 1px solid #ceddd3; border-radius: 22px; background: #fffdf8; box-shadow: 0 12px 30px #193b4a1a; animation: px-navigation-in 160ms var(--ease-emphasized); }
  html body #site #navigation .ed-nav-links.open>a { justify-content: space-between; min-block-size: 52px; padding: 12px 16px; border-radius: 12px; font-size: 17px; }
  html body #site #navigation .ed-nav-links.open>a[aria-current=page]::after { content: '•'; inline-size: 12px; color: #6e612e; font-size: 20px; }
}
@media(max-width:480px) {
