  html body #site #navigation .ed-brand { gap: 7px; font-size: 20px; }
  html body #site #navigation .ed-brand img { inline-size: 38px; block-size: 44px; }
  html body #site #navigation .ds-action.ds-primary { --action-icon: 30px; min-block-size: 44px; gap: 8px; padding-inline-start: 10px; font-size: 13px; }
  html body #site #navigation .ed-menu-toggle { min-inline-size: 44px; min-block-size: 44px; padding: 9px; border-radius: 12px; }
  html body #site #navigation .px-menu-label { display: none; }
  html body #site #navigation .ed-nav-links.open { max-block-size: calc(100dvh - 108px); }
}
@media(max-width:360px) {
  html body #site #navigation .ed-brand strong { display: none; }
  html body #site #navigation .ed-brand img { inline-size: 42px; block-size: 46px; }
  html body #site #navigation .ds-action.ds-primary { font-size: 14px; }
}
html body #site.active-assessment #navigation.ed-nav { display: flex; }
html body #site.active-assessment #navigation .ed-brand { font-size: 21px; }
@media(max-width:480px) {
  html body #site.active-assessment #navigation .ed-brand strong { display: none; }
  html body #site.active-assessment #navigation .ed-brand img { inline-size: 34px; block-size: 40px; }
  html body #site.active-assessment #navigation #assessment-nav-label { min-inline-size: 0; font-size: 13px; }
