@keyframes px-navigation-in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
@media(prefers-reduced-motion:reduce) {
  html body #site #navigation,html body #site #navigation * { transition: none !important; animation: none !important; }
}
